import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Build your team","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/team.md","filePath":"en/guides/team.md"}'),s={name:"en/guides/team.md"};function n(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/team.md for this page in Markdown format</div><h1 id="build-your-team" tabindex="-1">Build your team <a class="header-anchor" href="#build-your-team" aria-label="Permalink to &quot;Build your team&quot;">​</a></h1><p>Coding solo works fine — but when a task grows complex, an AI team lets you assemble roles the way you would in real life: each member gets a title, a system prompt, and a model suited to their work. Then you direct them all from one place.</p><h2 id="hiring-recruit-with-a-sentence" tabindex="-1">Hiring: recruit with a sentence <a class="header-anchor" href="#hiring-recruit-with-a-sentence" aria-label="Permalink to &quot;Hiring: recruit with a sentence&quot;">​</a></h2><p>Tell the main Agent &quot;I need a mail checker&quot; and it auto-decides the name, role, system prompt, and model — writing everything to <code>~/.kimi-code/agents/&lt;name&gt;.md</code>. You don&#39;t have to author any agent file yourself. If a same-name profile exists, the tool errors instead of silently overwriting.</p><blockquote><p><strong>Autonomous team-building discipline</strong>: When a needed capability doesn&#39;t have an existing member, the main Agent should autonomously decide the new member&#39;s name / role / description / prompt / model and execute the hire directly — without asking you item by item.</p></blockquote><p>The write takes effect immediately. The directory watcher auto-reloads, making the new member dispatchable right away — no CLI restart needed.</p><p>Want a subagent to stay on standby in the background while you work elsewhere? Add <code>duty: true</code> to that member&#39;s agent file. They will run without timeout (polling emails, watching repos, whatever) and won&#39;t auto-stop on timeout. You &quot;clock them out&quot; by having the main Agent send <code>TaskStop</code>.</p><h2 id="assigning-models-match-the-task-to-the-tool" tabindex="-1">Assigning models: match the task to the tool <a class="header-anchor" href="#assigning-models-match-the-task-to-the-tool" aria-label="Permalink to &quot;Assigning models: match the task to the tool&quot;">​</a></h2><p>Your <code>[models]</code> list (defined in <code>config.toml</code>) is the pool of available models for your team. Different tasks can be routed to different models:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;kimi-code/k3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;managed:kimi-code&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;k3&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_context_size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">262144</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;kimi-code/kimi-for-coding&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;managed:kimi-code&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi-for-coding&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_context_size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">262144</span></span></code></pre></div><p>To swap a member&#39;s model, say: &quot;Coder is too slow on k3, switch to kimi-for-coding.&quot; The main Agent updates <code>[subagent.model_overrides]</code> — this override <strong>takes priority over the profile&#39;s <code>model_preference</code>, but below explicitly passed tool parameters</strong>. To pin a member to a specific model permanently, set that id in the agent file&#39;s <code>model_preference</code> field instead.</p><table tabindex="0"><thead><tr><th>Level</th><th>Who controls</th><th>Scope</th></tr></thead><tbody><tr><td>Tool parameter</td><td>Agent on each dispatch</td><td>Single call only</td></tr><tr><td><code>[subagent.model_overrides]</code></td><td>Main Agent via chat command or TeamHire</td><td>Persistent, overrides profile default</td></tr><tr><td>frontmatter <code>model_preference</code></td><td>Written into the agent file itself</td><td>Persistent</td></tr></tbody></table><h2 id="managing-on-duty-deliver-messages-break-tasks" tabindex="-1">Managing on duty: deliver messages, break tasks <a class="header-anchor" href="#managing-on-duty-deliver-messages-break-tasks" aria-label="Permalink to &quot;Managing on duty: deliver messages, break tasks&quot;">​</a></h2><p>Once dispatched, how do you manage?</p><ul><li><strong>Background by default</strong>: In team mode, the main Agent dispatches subagents to run in the background by default — <code>run_in_background</code> is treated as <code>true</code> when omitted from the <code>Agent</code> tool. The dispatch returns a <code>task_id</code> immediately, and the result arrives automatically as a system message. The main Agent stays unblocked and can keep talking to you. Only an explicit <code>run_in_background=false</code> makes it wait synchronously.</li><li><strong>Check progress</strong>: Use <code>/tasks</code> (<code>TaskList</code>) and <code>TaskOutput</code> to inspect running background tasks and their output.</li><li><strong>Deliver mid-task corrections</strong>: Notice the agent veering off course? The main Agent can use <code>TeamMessage</code> to send a note directly into the running subagent&#39;s current turn — default is a soft reminder; pass <code>interrupt: true</code> to cancel the current turn first, then inject the new instruction (equivalent to pressing ESC twice in the terminal).</li><li><strong>Adjust concurrency</strong>: Use <code>TeamConcurrency</code> to view and dynamically adjust the session-level subagent concurrency cap — run 4 when the machine is idle, dial it down when resources are tight. Combine with the <code>[subagent] max_concurrency</code> config in <code>config.toml</code> for flexible team throughput control.</li><li><strong>Clock out</strong>: Use <code>TaskStop</code> to stop a running instance. Members with <code>duty: true</code> require an explicit <code>TaskStop</code> — they won&#39;t auto-stop on timeout.</li></ul><h2 id="performance-score-on-completion" tabindex="-1">Performance: score on completion <a class="header-anchor" href="#performance-score-on-completion" aria-label="Permalink to &quot;Performance: score on completion&quot;">​</a></h2><p>When work finishes, the main Agent reminds you with the current average score + model used. You can also score manually at any time with <code>TeamScore</code> (0–100 with notes).</p><p>Each score entry is attributed to the model id actually running at scoring time, persisted to <code>$KIMI_CODE_HOME/agents/performance.json</code> — grouped by profile name, each entry carrying timestamp, score, note, and the running model id. In team mode, each subagent run also records an automatic shift entry (duration, work summary, model, concurrency level) in the same file alongside the scores (both capped at FIFO 50), helping you estimate future scheduling. Once team mode is on, the <code>Agent</code> tool shows each member&#39;s average score directly in the member list.</p><p>When a member consistently scores low on a certain model, it signals a poor &quot;member × model&quot; pairing; the main Agent should switch via <code>[subagent.model_overrides]</code> or recommend another available id from your <code>[models]</code> list.</p><h2 id="team-status-at-a-glance" tabindex="-1">/team: status at a glance <a class="header-anchor" href="#team-status-at-a-glance" aria-label="Permalink to &quot;/team: status at a glance&quot;">​</a></h2><p>Team mode is off by default. Type <code>/team on</code> to enable it — the five management tools (<code>TeamHire</code>, <code>TeamFire</code>, <code>TeamScore</code>, <code>TeamMessage</code>, <code>TeamConcurrency</code>) become visible to the main Agent. Use <code>/team off</code> to disable it at any time.</p><p>Type <code>/team</code> in the terminal to open the team overview panel — every member&#39;s role, effective model, average score and count, all visible. Each subagent&#39;s call card also shows &quot;name · role · model · last score&quot;.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../customization/agents.html">Agent field reference</a> — Complete frontmatter field documentation</li><li><a href="./../configuration/config-files.html#subagent">Configuration — <code>model_overrides</code></a> — <code>[subagent.model_overrides]</code> config details</li></ul>`,25)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
